modules.usage:
module "foundation" {
  source = "github.com/appcd-dev/solutions//modules/aios-foundation?ref=main"

  stackgen_url   = var.stackgen_url
  stackgen_token = var.stackgen_token
  llm_api_keys   = {
    openai    = var.openai_api_key
    anthropic = var.anthropic_api_key
    gemini    = var.gemini_api_key
  }
}

module "foundation_bedrock" {
  source = "github.com/appcd-dev/solutions//modules/aios-foundation-bedrock?ref=main"

  stackgen_url   = var.stackgen_url
  stackgen_token = var.stackgen_token
  aws_region     = "us-east-1"
  bedrock_auth   = { use_iam_role = true }
}

module "policies" {
  source = "github.com/appcd-dev/solutions//modules/aios-policies?ref=main"

  create_policies = {
    azure_tool_governance  = false
    google_tool_governance = false
  }
}

module "onprem_runner" {
  source = "github.com/appcd-dev/solutions//modules/aios-remote-runner?ref=main"

  create_runner = true
  name          = "org-tofu-runner"
}

# Pass module.onprem_runner.runner_name to agent modules.

module "aws_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-aws?ref=main"

  aws_access_key_id     = var.aws_access_key_id
  aws_secret_access_key = var.aws_secret_access_key
}

module "gcp_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-gcp?ref=main"

  gcp_credentials_json = var.gcp_credentials_json
  gcp_project_id       = "my-project-id"
}

module "github_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-github?ref=main"

  github_token = var.github_token
}

module "grafana_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-grafana?ref=main"

  grafana_server = "https://grafana.example.com"
  grafana_token  = var.grafana_api_token
}

module "datadog_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-datadog?ref=main"

  datadog_api_key = var.datadog_api_key
  datadog_app_key = var.datadog_app_key
}

module "pagerduty_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-pagerduty?ref=main"

  api_token = var.pagerduty_api_token
}

module "firehydrant_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-firehydrant?ref=main"

  api_key = var.firehydrant_api_key
}

module "internal_tool" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-internal-tool?ref=main"

  base_url = "https://console.internal.example.com/api/v1"
  api_key  = var.internal_console_token
}

module "servicenow_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-servicenow?ref=main"

  instance_url = "https://your-org.service-now.com"
  username     = var.servicenow_username
  password     = var.servicenow_password
}

module "confluence_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-confluence?ref=main"

  base_url  = "https://yourorg.atlassian.net/wiki"
  email     = var.confluence_email
  api_token = var.confluence_api_token
}

module "paloalto_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-paloalto?ref=main"

  management_url = "https://fw-mgmt.internal.example.com"
  api_key      = var.paloalto_api_key
}

module "gitlab_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-gitlab?ref=main"

  base_url      = "https://gitlab.example.com"
  private_token = var.gitlab_token
}

module "argocd_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-argocd?ref=main"

  server_url = "https://argocd.example.com"
  auth_token = var.argocd_token
}

module "sonarqube_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-sonarqube?ref=main"

  server_url = "https://sonar.example.com"
  token      = var.sonarqube_token
}

module "langfuse_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-langfuse?ref=main"

  langfuse_public_key = var.langfuse_public_key
  langfuse_secret_key = var.langfuse_secret_key
}

module "slack_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-slack?ref=main"

  slack_bot_token      = var.slack_bot_token
  slack_signing_secret = var.slack_signing_secret
}

module "clickhouse_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-clickhouse?ref=main"

  clickhouse_host      = "abc123.us-east-1.aws.clickhouse.cloud"
  clickhouse_password  = var.clickhouse_password
  clickhouse_mcp_image = "your-registry/mcp-clickhouse:latest"
}

module "cursor_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-cursor?ref=main"

  cursor_api_key = var.cursor_api_key
}

module "linear_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-linear?ref=main"

  credential_provider_id = var.linear_oauth_provider_id
}

module "ubuntu_integration" {
  source = "github.com/appcd-dev/solutions//modules/aios-integration-ubuntu?ref=main"
}

module "sre_agents" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-sre?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = module.policies.policy_ids
  policy_create_flags = {
    sre_remediation          = module.policies.policy_create_flags.sre_remediation
    prod_write_gate          = module.policies.policy_create_flags.prod_write_gate
    tier0_service_protection = module.policies.policy_create_flags.tier0_service_protection
    blast_radius_limit       = module.policies.policy_create_flags.blast_radius_limit
    freeze_window            = module.policies.policy_create_flags.freeze_window
    data_risk_pii            = module.policies.policy_create_flags.data_risk_pii
    post_action_verification = module.policies.policy_create_flags.post_action_verification
  }

  integration_names = {
    grafana = module.grafana_integration.integration_name
    slack   = module.slack_integration.integration_name
  }
}

module "alert_triage" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-alert-triage?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  existing_grafana_integration_name = module.grafana_integration.integration_name
  existing_slack_integration_name   = module.slack_integration.integration_name
}

module "aws_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-aws-sre?ref=main"

  model_names      = module.foundation.model_names
  policy_ids       = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
  integration_name = module.aws_integration.integration_name
}

module "gcp_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-gcp-sre?ref=main"

  model_names      = module.foundation.model_names
  policy_ids       = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
  integration_name = "gcp-production"
}

module "azure_devops" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-azure-devops?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  integration_names = {
    azure = module.azure_integration.integration_name
    slack = module.slack_integration.integration_name
  }
}

module "azure_saas_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-azure-saas-sre?ref=main"

  model_names = module.foundation.model_names
  policy_ids = {
    dangerous_ops   = module.policies.policy_ids.dangerous_ops
    sre_remediation = module.policies.policy_ids.sre_remediation
  }

  confluence_space_key = "SRE"
  datadog_api_key      = var.datadog_api_key
  datadog_app_key      = var.datadog_app_key
  pagerduty_api_token  = var.pagerduty_api_token
  azure_secret_id      = module.azure_integration.secret_id
}

module "gitops_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-privatesaas-gitops-sre?ref=main"

  model_names = module.foundation.model_names
  policy_ids = {
    dangerous_ops   = module.policies.policy_ids.dangerous_ops
    sre_remediation = module.policies.policy_ids.sre_remediation
  }

  gitlab_base_url = "https://gitlab.internal.example.com"
  gitlab_private_token = var.gitlab_token
  aws_secret_id = module.aws_integration.secret_id
  slack_bot_token = var.slack_bot_token
}

module "selfhosted_infra" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-selfhosted-infra?ref=main"

  model_names = module.foundation.model_names
  policy_ids = {
    dangerous_ops   = module.policies.policy_ids.dangerous_ops
    sre_remediation = module.policies.policy_ids.sre_remediation
    prod_write_gate = module.policies.policy_ids.prod_write_gate
  }

  aws_secret_id = module.aws_integration.secret_id
  self_hosted_environment_label = "prod-us-east-1-vpc"
  cloudformation_stack_prefix_allowlist = ["prod-", "staging-"]
}

module "cfn_governance" {
  source = "github.com/appcd-dev/solutions//modules/aios-cfn-governance-runbooks?ref=main"

  org_baseline_name         = "acme-prod-baseline-v2"
  fedramp_profile           = "moderate"
  cfn_template_catalog_path = "cloudformation/catalog/"
}

module "aiden_infra" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-aiden-infra?ref=main"

  model_names = module.foundation_bedrock.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  target_repository_full_name = "org/infra-templates"
  github_secret_id            = module.github_integration.secret_id
  aws_secret_id               = module.aws_integration.secret_id

  enable_terraform_bot = true
  stackgen_token_secret_id = var.stackgen_token_secret_id
}

module "grafana_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-grafana-sre?ref=main"

  model_names       = module.foundation.model_names
  policy_ids        = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
  grafana_base_url  = "https://grafana.example.com"
  grafana_api_token = var.grafana_token
}

module "predictive_sre" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-predictive-sre?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  agent_names = {
    github_agent  = module.software_engineering.agent_names.cursor_developer
    grafana_agent = module.grafana_sre.agent_name
    aws_agent     = module.aws_sre.aws_sre_agent_name
  }
}

module "repo_to_iac" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-repo-to-iac?ref=main"

  model_names = module.foundation.model_names
  policy_ids = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
  github_integration_name = module.github_integration.integration_name
}

module "software_engineering" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-software-engineering?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  integration_names = {
    linear_mcp = "linear-integration"
    cursor_mcp = "cursor-tool"
    github     = module.github_integration.integration_name
  }
}

module "sdlc" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-sdlc?ref=main"

  model_names = module.foundation.model_names
  policy_ids = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  sre_agent_names   = { sre_risk_posture = module.sre.agent_names.sre_risk_posture }
  sre_runbook_names = { deployment_rollback = "argocd-rollback" }
}

module "supply_chain" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-supply-chain-security?ref=main"

  model_names               = module.foundation.model_names
  policy_ids                = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
  github_integration_name   = module.github_integration.integration_name
}

module "compliance" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-compliance-auditor?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = {
    dangerous_ops = module.policies.policy_ids.dangerous_ops
    data_risk_pii = module.policies.policy_ids.data_risk_pii
  }

  integration_names = {
    aws    = module.aws_integration.integration_name
    github = module.github_integration.integration_name
  }
}

module "cost_optimizer" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-cost-optimizer?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  integration_names = {
    aws   = module.aws_integration.integration_name
    azure = module.azure_integration.integration_name
  }
}

module "marketing" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-marketing?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }
}

module "onboarding" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-onboarding?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = { dangerous_ops = module.policies.policy_ids.dangerous_ops }

  integration_names = {
    slack  = module.slack_integration.integration_name
    github = module.github_integration.integration_name
  }
}

module "workspace" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-workspace-assistant?ref=main"

  model_names = module.foundation.model_names
  policy_ids  = {
    dangerous_ops          = module.policies.policy_ids.dangerous_ops
    google_tool_governance = module.policies.policy_ids.google_tool_governance
  }

  integration_names = {
    google = "google-workspace"
    slack  = module.slack_integration.integration_name
    linear = "linear-integration"
  }
}

module "ubuntu_cli" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-ubuntu-cli?ref=main"

  model_names = module.foundation.model_names
  policy_ids = {
    dangerous_ops        = module.policies.policy_ids.dangerous_ops
    container_shell_hitl = module.policies.policy_ids.container_shell_hitl
  }
  integration_names = {
    ubuntu_cli = module.ubuntu_integration.integration_name
  }
}

module "clickhouse_inspector" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-clickhouse-inspector?ref=main"

  model_names = module.foundation.model_names
  policy_ids = {
    dangerous_ops         = module.policies.policy_ids.dangerous_ops
    data_risk_pii         = module.policies.policy_ids.data_risk_pii
    azure_tool_governance = module.policies.policy_ids.azure_tool_governance
  }
  integration_names = {
    clickhouse = module.clickhouse_integration.integration_name
  }
}

module "db_optimizer" {
  source = "github.com/appcd-dev/solutions//modules/aios-agent-db-optimizer?ref=main"

  model_names = module.foundation.model_names
  integration_names = {
    datadog = module.datadog_integration.integration_name
    slack   = module.slack_integration.integration_name
  }
}

